<!doctype html>
<html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><meta name="robots" content="noindex,nofollow"><title>Eksport produktów do WystawCzesc</title>
<style>body{font:16px system-ui;background:#f5f6f8;color:#182337;margin:0}main{max-width:850px;margin:40px auto;padding:28px;background:white;border-radius:12px}label{display:block;margin:20px 0}select,button{font:inherit;padding:10px;border:1px solid #bdc7d2;border-radius:6px}button{cursor:pointer;background:#edf2f7;margin:5px}button:disabled{opacity:.5}progress{width:100%;height:24px}a{color:#174f91}#error{color:#9e2222;white-space:pre-wrap}li{margin:8px 0}</style></head>
<body><main><a href="/admin">← Panel GPSwiss</a><h1>Eksport produktów do WystawCzesc</h1>
<p>Najpierw przygotuj próbkę i sprawdź import. Pełny eksport odczyta dane ponownie. Zdjęcia kopiujesz osobno.</p>
<form id="form"><label>Rodzaj danych <select id="type"><option value="czesci">Części</option><option value="sprzedane">Sprzedane</option><option value="do_wystawienia">Do wystawienia</option></select></label>
<label>Tryb <select id="mode"><option value="sample">Próbka 5 produktów</option><option value="full">Pełny eksport</option></select></label>
<button id="prepare">Przygotuj eksport</button></form>
<p id="status" role="status" aria-live="polite">Gotowy do przygotowania</p><progress id="progress" value="0" max="1"></progress>
<p id="counts"></p><p id="sample"></p><button id="resume" disabled>Resume — wznów</button><button id="stop" disabled>Stop</button>
<p id="error" role="alert"></p><ul id="files"></ul><details><summary>Diagnostyka</summary><pre id="diagnostics"></pre></details>
</main><script>
const base=@json(route('admin.tools.product-migration-export', [], false)), key='gpswiss-product-export-'+@json((string)auth()->id()), el=id=>document.getElementById(id);
let id=localStorage.getItem(key), state=null, running=false, busy=false;
const labels={capturing:'Odczytywanie aktualnych danych',ready:'Przygotowywanie plików',stopped:'Zatrzymany',done:'Gotowy do pobrania',capture_failed:'Odczyt przerwany — przygotuj nowy eksport'};
async function call(action,body={}){const url=base+(id?'/'+id:'');const r=await fetch(url,{method:action?'POST':'GET',headers:{Accept:'application/json',...(action?{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content}:{})},...(action?{body:JSON.stringify({action,...body})}:{})});let s;try{s=await r.json();}catch(e){el('diagnostics').textContent=JSON.stringify({action:action||'status',http_status:r.status,reason_code:'non_json_server_response'},null,2);throw Error('Błąd serwera HTTP '+r.status+' — brak odpowiedzi JSON');}if(!r.ok){if(s.export_id){id=s.export_id;localStorage.setItem(key,id);}el('diagnostics').textContent=JSON.stringify(s.diagnostic||{action:action||'status',http_status:r.status,reason_code:s.error||'server_error'},null,2);throw Error(s.error||'Błąd przygotowania');}state=s;render();return s;}
function render(){el('status').textContent=labels[state.state]||state.state;el('progress').max=Math.max(1,state.total);el('progress').value=state.state==='capturing'?state.capture_processed||0:state.processed;el('counts').textContent=`Produkty: ${state.processed}/${state.total} · Zdjęcia: ${state.images} · Listingi: ${state.listings} · Problemy: ${state.issues}`;el('sample').textContent=state.mode==='sample'?'Próbka part_id: '+state.sample_part_ids.join(', '):'';el('diagnostics').textContent=JSON.stringify(state,null,2);el('files').replaceChildren();if(state.state==='done')for(const file of Object.keys(state.files)){const li=document.createElement('li'),a=document.createElement('a');a.textContent=file;a.href=base+'/'+id+'?download='+encodeURIComponent(file);li.append(a);el('files').append(li);}el('resume').disabled=!['ready','stopped'].includes(state.state)||busy;el('stop').disabled=state.state!=='ready';}
async function pump(){if(busy)return;busy=true;try{while(running&&state?.state==='ready'){await call('tick');await new Promise(resolve=>setTimeout(resolve,100));}}catch(e){running=false;el('error').textContent=e.message+' — możesz wznowić z ostatniego checkpointu.';}finally{busy=false;if(state)render();}}
el('form').onsubmit=async e=>{e.preventDefault();if(busy)return;running=false;busy=true;el('prepare').disabled=true;el('error').textContent='';el('files').replaceChildren();id=null;el('status').textContent='Odczytywanie aktualnych danych…';try{const s=await call('prepare',{type:el('type').value,mode:el('mode').value});id=s.export_id;localStorage.setItem(key,id);await call('capture');busy=false;running=true;await pump();}catch(e){el('error').textContent=e.message;}finally{busy=false;el('prepare').disabled=false;}};
el('resume').onclick=async()=>{if(busy)return;try{await call('resume');running=true;await pump();}catch(e){el('error').textContent=e.message;}};
el('stop').onclick=async()=>{running=false;try{while(busy)await new Promise(resolve=>setTimeout(resolve,50));await call('stop');}catch(e){el('error').textContent=e.message;}};
async function restore(){try{await call();el('type').value=state.type;el('mode').value=state.mode;if(state.state==='capturing')setTimeout(restore,3000);}catch(e){el('error').textContent=e.message;}}
if(id)restore();
</script></body></html>
